CREATE TABLE IF NOT EXISTS sacrament_meetings (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  meeting_date DATE NOT NULL,
  meeting_data JSONB NOT NULL,
  CONSTRAINT sacrament_meetings_json_id_matches
    CHECK ((meeting_data->>'id')::integer = id),
  CONSTRAINT sacrament_meetings_json_date_matches
    CHECK (meeting_data->>'date' = meeting_date::text)
);

CREATE INDEX IF NOT EXISTS sacrament_meetings_date_idx
  ON sacrament_meetings (meeting_date DESC, id DESC);

